package gg.pixelkingdomwars.nativeclient.divine
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class DivineProtocolTest {
 private val f=Json.parseToJsonElement(javaClass.classLoader!!.getResource("divine-trial-vectors.json")!!.readText()).jsonObject
 private val rules=DivineRules.installed(f.dobj("policy"),f.dobj("validationConstants"));private val event=f.dobj("event");private val plans=f.drows("plans").map{it.dobj("attempt")}
 private fun change(o:JsonObject,key:String,value:JsonElement)=JsonObject(o+(key to value))
 private fun rejects(block:()->Unit){assertTrue(runCatching(block).isFailure)}
 @Test fun `all four actual simulator outcomes preserve exact canonical input commitments`() {rules.event(event);rules.entry(f.getValue("entry"));plans.forEach{rules.attempt(it);rules.orders(it.getValue("orders"),it.dobj("encounter"))};assertEquals("969df9abb3d0e522428e1b46e6e6d5514695899bddd90fb1949addea5c549009",event.dobj("encounter").dt("inputSha256"))}
 @Test fun `encounter substitution and altered command coordinates cannot keep original hashes`() {val a=plans.first();val e=a.dobj("encounter");rejects{rules.encounter(change(e,"seed",JsonPrimitive(e.dn("seed")+1)))};val orders=a.dobj("orders");val d=orders.drows("deploys");val replaced=change(orders,"deploys",JsonArray(listOf(change(d.first(),"tx",JsonPrimitive(d.first().dn("tx")+1)))+d.drop(1)));rejects{rules.attempt(change(a,"orders",replaced))}}
 @Test fun `fixed complete army rejects missing extra substituted or timed orders`() {val a=plans.first();val o=a.dobj("orders");val d=o.drows("deploys");for(next in listOf(d.drop(1),d+d.first(),listOf(change(d.first(),"troop",JsonPrimitive("dragon")))+d.drop(1),listOf(change(d.first(),"tMs",JsonPrimitive(1)))+d.drop(1)))rejects{rules.orders(change(o,"deploys",JsonArray(next)),a.dobj("encounter"))};val center=change(d.first(),"tx",JsonPrimitive(15));rejects{rules.orders(change(o,"deploys",JsonArray(listOf(change(center,"ty",JsonPrimitive(15)))+d.drop(1))),a.dobj("encounter"))}}
 @Test fun `funded terminal independently checks rank order occupation mapping and every stock remainder`() {val t=f.dobj("terminal");val settled=change(event,"terminal",t);rules.event(settled);val ent=t.drows("entitlements");val first=ent.first();val amounts=first.dobj("amounts");val k=amounts.keys.first();val altered=change(first,"amounts",change(amounts,k,JsonPrimitive((amounts.dt(k).toBigInteger()+java.math.BigInteger.ONE).toString())));rejects{rules.event(change(event,"terminal",change(t,"entitlements",JsonArray(listOf(altered)+ent.drop(1)))))};rejects{rules.event(change(event,"terminal",change(t,"rankings",JsonArray(t.drows("rankings").reversed()))))}}
 @Test fun `qualification counters are exact u64 strings rather than numeric or rounded values`() {val e=f.dobj("entry");val q=e.dobj("qualification");rules.entry(change(e,"qualification",change(q,"sequence",JsonPrimitive("18446744073709551615"))));for(v in listOf(JsonPrimitive("18446744073709551616"),JsonPrimitive(1),JsonPrimitive("01")))rejects{rules.entry(change(e,"qualification",change(q,"sequence",v)))}}
 @Test fun `unknown replay families future fields bad ticks and terminal rollback hold`() {val a=plans.first();val r=a.dobj("result");val rows=r.drows("events");for(e in listOf(change(rows.first(),"e",JsonPrimitive("reward")),JsonObject(rows.first()+("bonus" to JsonPrimitive(1))),change(rows.first(),"t",JsonPrimitive(-1))))rejects{rules.attempt(change(a,"result",change(r,"events",JsonArray(listOf(e)+rows.drop(1)))))};rejects{rules.attempt(change(a,"status",JsonPrimitive("admitted")))};rejects{rules.attempt(change(a,"completedAt",JsonNull))}}
 @Test fun `parser and transport grammar cannot widen routes identifiers or canonical numbers`() {rejects{DivineGrammar.request("POST","/raids",emptyMap(),buildJsonObject{})};rejects{DivineGrammar.request("GET","/divine-trials/events/../participant",emptyMap(),null)};rejects{DivineGrammar.request("GET","/divine-trials/events",mapOf("wallet" to "other"),null)};rejects{DivineGrammar.canonical(Json.parseToJsonElement("{\"n\":9007199254740992}"))};rejects{DivineGrammar.canonical(Json.parseToJsonElement("{\"n\":0.5}"))};assertEquals("{\"a\":0,\"z\":1}",DivineGrammar.canonical(Json.parseToJsonElement("{\"z\":1,\"a\":0}")))}
 @Test fun `participant cannot omit accepted ordinal or borrow another wallet`() {val e=f.dobj("entry");val a=plans.first();val p=buildJsonObject{put("version",1);put("eventId",event.getValue("id"));put("wallet",e.getValue("wallet"));put("entry",e);put("attempts",JsonArray(listOf(a)));put("prize",JsonNull)};rules.participant(p,e.dt("wallet"),event.dt("id"));rejects{rules.participant(p,"another",event.dt("id"))};rejects{rules.participant(change(p,"attempts",JsonArray(listOf(change(a,"ordinal",JsonPrimitive(2))))),e.dt("wallet"),event.dt("id"))}}
}
